begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id) values('de900000-0000-4000-8000-000000000001'),('de900000-0000-4000-8000-000000000002'),('de900000-0000-4000-8000-000000000003');
insert into profiles(id) select id from auth.users where id in('de900000-0000-4000-8000-000000000001','de900000-0000-4000-8000-000000000002','de900000-0000-4000-8000-000000000003');
insert into user_roles(user_id,role_id) select 'de900000-0000-4000-8000-000000000001',id from roles where code='SUPER_ADMIN';
insert into user_roles(user_id,role_id) select 'de900000-0000-4000-8000-000000000002',id from roles where code='STUDENT';
insert into user_roles(user_id,role_id) select 'de900000-0000-4000-8000-000000000003',id from roles where code='STUDENT';
select set_config('request.jwt.claim.sub','de900000-0000-4000-8000-000000000001',true);
set local role authenticated;
select is(enqueue_notification_event('ONBOARDING','de900000-0000-4000-8000-000000000002'),1,'Create onboarding job');
select is(enqueue_notification_event('ONBOARDING','de900000-0000-4000-8000-000000000002'),0,'Duplicate enqueue does not create another job');
select is((select status from notification_jobs where recipient_id='de900000-0000-4000-8000-000000000002'),'PENDING','Creation never pretends delivery');
select throws_ok($$update notification_jobs set status='SENT'$$,'42501',null,'Direct queue write denied');
select throws_ok($$select * from claim_notification('de900000-0000-4000-8000-000000000002')$$,'42501',null,'Authenticated cannot claim provider work');
select throws_ok($$select complete_notification('de900000-0000-4000-8000-000000000002','de900000-0000-4000-8000-000000000002','fake')$$,'42501',null,'Authenticated cannot forge receipt');
select lives_ok($$select deliver_in_app_notification(id) from notification_jobs where recipient_id='de900000-0000-4000-8000-000000000002'$$,'In-app delivery is atomic');
select lives_ok($$select deliver_in_app_notification(id) from notification_jobs where recipient_id='de900000-0000-4000-8000-000000000002'$$,'Repeated in-app delivery is harmless');
select is((select attempts from notification_jobs where recipient_id='de900000-0000-4000-8000-000000000002'),1,'Only one claimed attempt');
select set_config('request.jwt.claim.sub','de900000-0000-4000-8000-000000000002',true);
select is((select count(*) from own_notifications()),1::bigint,'Recipient sees confirmed inbox item');
select is((select count(*) from notification_jobs),0::bigint,'Recipient cannot inspect queue');
select throws_ok($$select enqueue_notification_event('ONBOARDING','de900000-0000-4000-8000-000000000003')$$,'P0001','Unauthorized','Non-admin enqueue denied');
select set_config('request.jwt.claim.sub','de900000-0000-4000-8000-000000000003',true);
select is((select count(*) from own_notifications()),0::bigint,'Cross-account inbox denied');
reset role;
select set_config('request.jwt.claim.sub','de900000-0000-4000-8000-000000000001',true);
update profiles set status='INACTIVE' where id='de900000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','de900000-0000-4000-8000-000000000002',true);
select is((select count(*) from own_notifications()),0::bigint,'Inactive recipient denied existing notice');
select set_config('request.jwt.claim.sub','de900000-0000-4000-8000-000000000001',true);
update profiles set status='ACTIVE' where id='de900000-0000-4000-8000-000000000002';
update user_roles set valid_until=now()-interval '1 second' where user_id='de900000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','de900000-0000-4000-8000-000000000002',true);
select is((select count(*) from own_notifications()),0::bigint,'Expired role denied existing notice');
select set_config('request.jwt.claim.sub','de900000-0000-4000-8000-000000000001',true);
update user_roles set valid_until=null where user_id='de900000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','de900000-0000-4000-8000-000000000001',true);
select is(enqueue_notification_event('ONBOARDING','de900000-0000-4000-8000-000000000002','EMAIL','MOCK'),1,'Mock job distinct from real delivery');
create temp table notification_claim as select * from claim_notification((select id from notification_jobs where delivery_mode='MOCK' and recipient_id='de900000-0000-4000-8000-000000000002'));
select is((select count(*) from claim_notification((select id from notification_claim))),0::bigint,'Already claimed job cannot be sent concurrently');
select throws_ok($$select complete_notification(id,lease_token) from notification_claim$$,'P0001','Provider confirmation required','Missing confirmation cannot mark SENT');
select lives_ok($$select complete_notification(id,lease_token,null,'PROVIDER_REJECTED') from notification_claim$$,'Provider failure recorded');
select is((select status from notification_jobs where id=(select id from notification_claim)),'FAILED','Provider failure not SENT');
select lives_ok($$select manage_notification(id,'RETRY') from notification_claim$$,'Failed job can retry');
truncate notification_claim;
insert into notification_claim select * from claim_notification((select id from notification_jobs where delivery_mode='MOCK' and recipient_id='de900000-0000-4000-8000-000000000002'));
select lives_ok($$select complete_notification(id,lease_token,'mock:confirmed') from notification_claim$$,'Provider confirmation records successful MOCK');
select is((select attempts from notification_jobs where id=(select id from notification_claim)),2,'Retry increments attempt on same job');
select is((select count(*) from notification_inbox where recipient_id='de900000-0000-4000-8000-000000000002'),1::bigint,'Mock does not pollute real inbox');
select throws_ok($$select manage_notification(id,'RETRY') from notification_claim$$,'P0001','Invalid notification transition','SENT cannot retry');
select throws_ok($$select complete_notification(id,lease_token,'mock:again') from notification_claim$$,'P0001','Stale delivery lease','Duplicate acknowledgement rejected');
select ok(not has_function_privilege('anon','public.own_notifications(integer)','EXECUTE'),'Anonymous inbox denied');
select ok(not has_table_privilege('service_role','public.notification_jobs','UPDATE'),'Service worker cannot bypass queue RPC');
select * from finish();
rollback;
